// Committed structure evidence stays readable; only path prefixes are compacted.
import { createHash, randomUUID } from 'node:crypto';
import { lstat, mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { BaselineEntry, StructureElement, StructureSnapshot } from '../types.js';
import { decodeStructure } from '../capture/structure.js';

export const STRUCTURE_DIR = 'juxtapose.structures';
export const GENERATED_NOTE =
  'Generated by Juxtapose. Do not edit manually. Update with jux approve.';
const README = `# Generated baseline structures\n\n${GENERATED_NOTE}\n\nCommit this directory alongside juxtapose.manifest.json. These readable JSON\nfiles explain visual changes; image hashes in the manifest decide pass/fail.\nEach element occupies one line. A segment is relative to its indexed parent;\na full path is retained when it cannot be represented relative to that parent.\n`;

type StoredElement = Omit<StructureElement, 'path'> &
  ({ segment: string } | { path: string });
export interface StoredStructure extends Omit<StructureSnapshot, 'schema' | 'elements'> {
  schema: 'juxtapose.structure/compact-v1';
  elements: StoredElement[];
}

export function compactStructure(snapshot: StructureSnapshot): StoredStructure {
  const elements = snapshot.elements.map(({ path: full, ...element }) => {
    if (typeof full !== 'string') throw new Error('invalid structure path');
    const parent = element.parent;
    const prefix = parent !== null ? snapshot.elements[parent]?.path : undefined;
    return prefix !== undefined && full.startsWith(`${prefix}>`)
      ? { segment: full.slice(prefix.length + 1), ...element }
      : { path: full, ...element };
  });
  for (let i = 0; i < elements.length; i++) {
    const parent = elements[i]!.parent;
    if (parent !== null && (!Number.isInteger(parent) || parent < 0 || parent >= i))
      throw new Error('invalid structure parent');
  }
  return { ...snapshot, schema: 'juxtapose.structure/compact-v1', elements };
}

export function expandStructure(stored: StoredStructure): StructureSnapshot {
  if (
    stored.schema !== 'juxtapose.structure/compact-v1' ||
    !Array.isArray(stored.elements)
  )
    throw new Error('invalid compact structure');
  const elements: StructureElement[] = [];
  for (const entry of stored.elements) {
    const { parent } = entry;
    if (
      parent !== null &&
      (!Number.isInteger(parent) || parent < 0 || parent >= elements.length)
    )
      throw new Error('invalid structure parent');
    if ('segment' in entry) {
      const { segment, ...rest } = entry;
      if (parent === null || typeof segment !== 'string' || 'path' in entry)
        throw new Error('invalid path segment');
      elements.push({ path: `${elements[parent]!.path}>${segment}`, ...rest });
    } else {
      if (typeof entry.path !== 'string') throw new Error('invalid structure path');
      elements.push({ ...entry });
    }
  }
  return decodeStructure(
    Buffer.from(
      JSON.stringify({ ...stored, schema: 'juxtapose.structure/v1', elements }),
    ),
  );
}

export function formatCompactStructure(snapshot: StructureSnapshot): Buffer {
  const { elements, ...head } = compactStructure(snapshot);
  return Buffer.from(
    `{\n${Object.entries(head)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
      .map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)},`)
      .join(
        '\n',
      )}\n  "elements": [${elements.length ? '\n' + elements.map((e) => '    ' + JSON.stringify(e)).join(',\n') + '\n  ' : ''}]\n}\n`,
  );
}

export function structureFile(storyId: string): string {
  let encoded = encodeURIComponent(storyId).replace(
    /[A-Z.]/g,
    (c) => '%' + c.charCodeAt(0).toString(16),
  );
  // Keep case-distinct IDs distinct on macOS/Windows and avoid device names.
  if (/^(con|prn|aux|nul|com[1-9]|lpt[1-9])$/i.test(encoded))
    encoded = '%' + encoded.charCodeAt(0).toString(16) + encoded.slice(1);
  const name =
    encoded.length > 180
      ? `${encoded.slice(0, 100)}-${digest(Buffer.from(storyId))}`
      : encoded;
  return `${STRUCTURE_DIR}/${name}.json`;
}
const digest = (bytes: Buffer): string =>
  createHash('sha256').update(bytes).digest('hex');

async function realDirectory(root: string, create: boolean): Promise<string> {
  const dir = path.join(root, STRUCTURE_DIR);
  if (create) await mkdir(dir, { recursive: true });
  if (!(await lstat(dir)).isDirectory())
    throw new Error('structure directory must be a real directory');
  return dir;
}

export async function writeStructureFile(
  root: string,
  storyId: string,
  snapshot: StructureSnapshot,
): Promise<Pick<BaselineEntry, 'structureFile' | 'structureFileHash'>> {
  const dir = await realDirectory(root, true);
  await writeFile(path.join(dir, 'README.md'), README, { flag: 'wx' }).catch(
    (err: unknown) => {
      if (!(err instanceof Error && 'code' in err && err.code === 'EEXIST')) throw err;
    },
  );
  const relative = structureFile(storyId);
  const file = path.join(root, relative);
  const bytes = formatCompactStructure(snapshot);
  // Reapproving identical evidence does not rewrite the file.
  const existing = await lstat(file).catch(() => null);
  if (!existing?.isFile() || !(await readFile(file)).equals(bytes)) {
    const temporary = `${file}.${randomUUID()}.tmp`;
    try {
      await writeFile(temporary, bytes, { flag: 'wx' });
      await rename(temporary, file);
    } finally {
      await rm(temporary, { force: true });
    }
  }
  return { structureFile: relative, structureFileHash: digest(bytes) };
}

export async function readStructureFile(
  root: string,
  storyId: string,
  entry: BaselineEntry,
): Promise<Buffer | null> {
  try {
    if (entry.structureFile !== structureFile(storyId) || !entry.structureFileHash)
      return null;
    await realDirectory(root, false);
    const file = path.join(root, entry.structureFile);
    if (!(await lstat(file)).isFile()) return null;
    const bytes = await readFile(file);
    if (digest(bytes) !== entry.structureFileHash) return null;
    const snapshot = expandStructure(
      JSON.parse(bytes.toString('utf8')) as StoredStructure,
    );
    if (snapshot.structureHash !== entry.structureHash) return null;
    return Buffer.from(JSON.stringify(snapshot));
  } catch {
    return null;
  }
}
